          opacity: 0.5;
          filter: blur(8px);
          animation: pay-fees-glow 3s ease-in-out infinite;
        }
        
        .pay-fees-cta::after {
          content: '';
          position: absolute;
          inset: -2px;
          border-radius: 9999px;
          background: linear-gradient(135deg, #f5d98a, #c9a84c, #b8942a);
